/* @lc app=leetcode id=3923 lang=kotlin */ class Solution { fun minGenerations(points: Array<IntArray>, target: IntArray): Int = (target[0] * 49 + target[1] * 7 + target[2]).let { tg -> generateSequence(points.map { it[0] * 49 + it[1] * 7 + it[2] }.toSet() to 0) { (s, k) -> if (tg in s) null else s.toList().let { l -> (s + l.indices.flatMap { i -> (i + 1 until l.size).map { j -> ((l[i] / 49 + l[j] / 49) / 2) * 49 + (((l[i] / 7) % 7 + (l[j] / 7) % 7) / 2) * 7 + ((l[i] % 7 + l[j] % 7) / 2) } }).let { ns -> if (ns.size == s.size) null else ns to k + 1 } } }.last().let { (s, k) -> if (tg in s) k else -1 } } }